"const resp = await page.goto('http://127.0.0.1:5173/', { waitUntil: 'domcontentloaded' });
const title = await page.title();
const bodyText = await page.locator('body').innerText();
return {
  status: resp.status(),
  title,
  bodySnippet: bodyText.slice(0, 1000)
};"

"let res1, res2;
try {
  const r1 = await page.goto('http://127.0.0.1:5173/', { timeout: 4000 });
  res1 = { status: r1?.status() };
} catch(e) {
  res1 = { error: e.message };
}

try {
  const r2 = await page.goto('http://localhost:5173/', { timeout: 4000 });
  res2 = { status: r2?.status() };
} catch(e) {
  res2 = { error: e.message };
}

return { res1, res2, url: page.url() };"

"try {
  const resp = await page.goto('http://127.0.0.1:5173/', { timeout: 5000 });
  return { ok: true, status: resp ? resp.status() : null, url: page.url() };
} catch (e) {
  return { ok: false, error: e.message, url: page.url() };
}"

