"const results = {};

const locations = [
  "Punjab - Ludhiana District",
  "Assam - Jorhat / Upper Assam",
  "Maharashtra - Nashik Region",
  "Uttar Pradesh - Varanasi District",
  "Spain - Valencia / Mediterranean"
];

for (const loc of locations) {
  await page.locator('select').first().selectOption({ label: loc });
  // Read snapshot details
  const widgetText = await page.locator('main').locator('div').filter({ hasText: /Local Agro-Climatic Snapshot|Simulated micro-station/ }).first().innerText();
  results[loc] = widgetText;
}

return results;"

"// Scroll to recommender section
await page.locator('#recommender').scrollIntoViewIfNeeded();

// Switch season to Kharif
await page.getByRole('button', { name: 'Kharif', exact: true }).click();

// Adjust Nitrogen slider to 120
const nSlider = page.locator('input[type="range"]').nth(0);
await nSlider.fill('120');

// Adjust Phosphorus slider to 60
const pSlider = page.locator('input[type="range"]').nth(1);
await pSlider.fill('60');

// Adjust Potassium slider to 45
const kSlider = page.locator('input[type="range"]').nth(2);
await kSlider.fill('45');

// Adjust pH slider to 6.2
const phSlider = page.locator('input[type="range"]').nth(3);
await phSlider.fill('6.2');

// Read top ranked crop recommendations
const recommenderText = await page.locator('#recommender').innerText();

return {
  recommenderPreview: recommenderText.slice(0, 1500)
};"

"// Click "View Complete Farming Plan"
await page.locator('ref=e96').click();

// Wait for modal to appear
const modal = page.locator('div[role="dialog"]').or(page.locator('.fixed.inset-0'));
await modal.first().waitFor({ state: 'visible', timeout: 5000 });

// Extract modal contents
const modalText = await modal.first().innerText();

return {
  modalContent: modalText
};"

"// Close modal
await page.locator('ref=e100').click();

// Scroll to Seasonal Farming Calendar
await page.locator('#calendar').scrollIntoViewIfNeeded();

// Check initial tabs and content
const tabStatus = {};

// Click "Kharif (Monsoon)"
await page.getByRole('button', { name: /Kharif \(Monsoon\)/i }).click();
tabStatus.kharifCards = await page.locator('#calendar h3').allInnerTexts();

// Click "Rabi (Winter)"
await page.getByRole('button', { name: /Rabi \(Winter\)/i }).click();
tabStatus.rabiCards = await page.locator('#calendar h3').allInnerTexts();

// Click "Zaid (Summer)"
await page.getByRole('button', { name: /Zaid \(Summer\)/i }).click();
tabStatus.zaidCards = await page.locator('#calendar h3').allInnerTexts();

// Click "All Seasons"
await page.getByRole('button', { name: /All Seasons/i }).click();
tabStatus.allSeasonsCards = await page.locator('#calendar h3').allInnerTexts();

// Test checklist checkbox interaction
const firstCheckbox = page.locator('#calendar input[type="checkbox"]').first();
const initialChecked = await firstCheckbox.isChecked();
await firstCheckbox.check();
const afterCheck = await firstCheckbox.isChecked();

return {
  tabStatus,
  checkboxToggle: { initialChecked, afterCheck }
};"

"// Scroll to Crop Doctor
await page.locator('#doctor').scrollIntoViewIfNeeded();

// Clear selection first to test from clean state
await page.getByRole('button', { name: /Clear Selection/i }).click();

// Select Crop: Rice
await page.getByRole('button', { name: 'Rice', exact: true }).click();

// Select Plant Part: Leaf
await page.getByRole('button', { name: 'Leaf', exact: true }).click();

// Select Symptoms: Brown / Black Spots
await page.getByRole('button', { name: /Brown \/ Black Spots/i }).click();

// Click "Analyze Symptoms & Diagnose"
await page.getByRole('button', { name: /Analyze Symptoms & Diagnose/i }).click();

// Read diagnostic report
const reportSection = page.locator('#doctor').locator('div').filter({ hasText: /Agronomic Diagnostic Report/i }).first();
const reportText = await reportSection.innerText();

return {
  reportText: reportText.slice(0, 1500)
};"

"// Scroll to Mandi & Schemes
await page.locator('#mandi').scrollIntoViewIfNeeded();

// Find search filter input
const searchInput = page.getByPlaceholder(/Filter by crop, state, or market mandi/i);
await searchInput.fill('Tomato');

// Get filtered row count / text
const tomatoRows = await page.locator('#mandi table tbody tr').allInnerTexts();

// Search for another commodity: Mustard
await searchInput.fill('Mustard');
const mustardRows = await page.locator('#mandi table tbody tr').allInnerTexts();

// Clear search
await searchInput.clear();
const allRowsCount = await page.locator('#mandi table tbody tr').count();

// Scroll to schemes section and click "View Application Steps" on PM-KISAN
const pmKisanBtn = page.getByRole('button', { name: /View Application Steps/i }).first();
await pmKisanBtn.scrollIntoViewIfNeeded();
await pmKisanBtn.click();

// Wait for scheme modal
const modal = page.locator('.fixed.inset-0').filter({ hasText: /Application Steps|PM-KISAN/i });
await modal.first().waitFor({ state: 'visible', timeout: 5000 });
const modalText = await modal.first().innerText();

// Close modal
const closeBtn = modal.locator('button').filter({ hasText: /Close/i }).first();
await closeBtn.click();

return {
  searchTomato: tomatoRows,
  searchMustard: mustardRows,
  totalTableRows: allRowsCount,
  pmKisanModalSnippet: modalText.slice(0, 800)
};"

"// Click "Ask Krishi AI" floating button
await page.locator('ref=e91').click();

// Wait for drawer to appear
const drawer = page.locator('div').filter({ hasText: /Krishi AI Agronomist|Ask Krishi AI/i }).first();
await drawer.waitFor({ state: 'visible', timeout: 5000 });

// Find quick prompt chips
const chip = page.locator('button').filter({ hasText: /Best fertilizer for paddy in clay soil\?|clay soil/i }).first();
await chip.click();

// Wait for AI response to appear in chat
await page.waitForTimeout(1000); // Wait for simulated streaming / response
const chatMessages = await page.locator('.space-y-4, [role="log"], .overflow-y-auto').allInnerTexts();

// Test simulated voice input button
const micBtn = page.locator('button[title*="voice" i], button[aria-label*="voice" i], button:has(svg)').filter({ hasText: /mic|voice/i }).or(page.locator('button').filter({ has: page.locator('svg') }).last());
// Let's inspect the drawer controls and buttons
const drawerButtons = await page.locator('button').allInnerTexts();

return {
  drawerVisible: true,
  chatSnippet: chatMessages.join('\n').slice(0, 1500),
  buttonsInDrawer: drawerButtons.filter(b => b.trim().length > 0)
};"

"// Click voice input button
const voiceBtn = page.locator('ref=e134');
await voiceBtn.click();

// Wait for voice simulation to populate input or start listening
await page.waitForTimeout(1000);

// Check input value or chat state
const inputValue = await page.locator('ref=e133').inputValue();

// If not auto-sent, click send button ref=e135
if (inputValue.length > 0) {
  await page.locator('ref=e135').click();
  await page.waitForTimeout(1000);
}

// Read latest chat messages
const chatLog = await page.locator('ref=e132').innerText();

return {
  voiceInputValue: inputValue,
  chatLogSnippet: chatLog.slice(-1000)
};"

"// Wait 2.5 seconds for simulated speech recognition
await page.waitForTimeout(2500);

// Check if voice transcribed text entered input or sent automatically
const inputValue = await page.locator('ref=e133').inputValue();
const chatText = await page.locator('ref=e132').innerText();

return {
  inputValue,
  chatTextSnippet: chatText.slice(-800)
};"

"// Close AI drawer
await page.locator('ref=e127').click();

// Wait for drawer to close
await page.waitForTimeout(500);

// Check all img elements
const images = page.locator('img');
const imgCount = await images.count();
const imgDetails = [];
for (let i = 0; i < imgCount; i++) {
  const img = images.nth(i);
  const src = await img.getAttribute('src');
  const alt = await img.getAttribute('alt');
  const isVis = await img.isVisible();
  imgDetails.push({ index: i, src, alt, isVis });
}

// Check page title and scroll back to top
await page.keyboard.press('Home');
await page.waitForTimeout(300);

return {
  imgCount,
  imgDetails,
  finalUrl: page.url()
};"

